# Один диагностический понедельник–воскресенье. Это наши проектные рейсы, не P03 assignments.
base=date(2028,6,5);assert base.weekday()==0
blocks={'OMS':170,'NJC':190,'PEE':80,'MRV':150,'MCX':150,'SVX':100}
legs=[]
def loop(pid,tail,day,path,start_min=240):
    t=datetime.combine(base+timedelta(days=day),datetime.min.time(),tzinfo=timezone.utc)+timedelta(minutes=start_min)
    for idx,(a,b) in enumerate(zip(path,path[1:])):
        duration=blocks[b if a=='KZN' else a] if 'KZN' in [a,b] else None
        if duration is None:raise ValueError((a,b))
        end=t+timedelta(minutes=duration)
        legs.append(dict(programme_id=pid,tail_template_id=tail,flight_id=f'{pid}-{day+1}-{tail}-{idx+1}',origin=a,destination=b,departure_utc=t.isoformat(),arrival_utc=end.isoformat(),block_min=duration,turn_after_min=45 if idx<len(path)-2 else 'end_of_chain',period='2028-06-05/11 diagnostic only',unit='proposed physical leg; minutes; UTC',coverage='частичный сценарный шаблон; не весь2027–2028 и не свободныйRWпарк',status='CONDITIONAL_DESIGN',source_id='KZN-LOCAL-DESIGN',assumption_ids='A-KZN-03;A-KZN-04;A-KZN-06;A-KZN-17'))
        t=end+timedelta(minutes=45)
for day,spokes in enumerate([['MRV','PEE'],['OMS'],['MCX'],['MRV','PEE'],['OMS','MRV'],['MCX'],['OMS']]):
    path=['KZN']
    for s in spokes:path +=[s,'KZN']
    loop('P-KZN-R1','T1',day,path)
for day,spoke in enumerate(['MRV','OMS','MCX','MRV','OMS','MCX']):loop('P-KZN-C1','T1',day,['SVX','KZN',spoke,'KZN','SVX'])
# Две встречные половины волны: прибывают в09:30Z, отправляются в11:00Z.
for day,north,south in [(0,'OMS','MRV'),(3,'OMS','MRV'),(1,'NJC','MCX'),(4,'NJC','MCX')]:
    # Подбирается первое отправление, чтобы с 45min turnaround вернуться в09:30Z.
    for tail,first,second in [('T1',north,south),('T2',south,north)]:
        start=570-2*blocks[first]-45
        # Две отдельные RT, между ними 90min для passengers, а не 45min turn.
        loop('P-KZN-W2',tail,day,['KZN',first,'KZN'],start)
        loop('P-KZN-W2',tail,day,['KZN',second,'KZN'],660)
# loop IDs reset for two RT in W2; make IDs unique and preserve source sequence.
for i,l in enumerate(legs,1):l['flight_id']=f"{l['programme_id']}-LEG-{i:03}"
for l in [dict(x) for x in legs if x['programme_id']=='P-KZN-W2']:
    l['programme_id']='P-KZN-R2';l['flight_id']=l['flight_id'].replace('W2','R2');legs.append(l)
table('proposed_legs_diagnostic.csv',legs)
checks=[]
for pid in ['P-KZN-R1','P-KZN-C1','P-KZN-W2','P-KZN-R2']:
    ll=[l for l in legs if l['programme_id']==pid];taildays={}
    for l in ll:taildays.setdefault((l['tail_template_id'],l['departure_utc'][:10]),[]).append(l)
    ok=True;spans=[];mins=[]
    for key,ls in taildays.items():
        ls.sort(key=lambda x:x['departure_utc']);spans.append((datetime.fromisoformat(ls[-1]['arrival_utc'])-datetime.fromisoformat(ls[0]['departure_utc'])).total_seconds()/60)
        for a,b in zip(ls,ls[1:]):
            gap=(datetime.fromisoformat(b['departure_utc'])-datetime.fromisoformat(a['arrival_utc'])).total_seconds()/60;mins.append(gap)
            ok &= a['destination']==b['origin'] and gap>=45
    checks.append(dict(programme_id=pid,leg_count=len(ll),block_min=sum(x['block_min'] for x in ll),active_tail_templates=len(set(x['tail_template_id'] for x in ll)),max_tail_day_span_min=max(spans),minimum_adjacent_ground_min=min(mins),position_and_turn_screen='PASS' if ok else 'FAIL',crew='UNKNOWN; длинный день борта не допуск рабочего дня экипажа',mro='UNKNOWN',slots='UNKNOWN',real_available_tails='UNKNOWN',status='ARITHMETIC_ONLY_NOT_OPERATIONAL_ACCEPTANCE',period='2028-06-05/11',unit='legs;minutes;tail templates',source_id='KZN-LOCAL-DESIGN',coverage='только собственная конструкция',assumption_ids='A-KZN-03;A-KZN-04;A-KZN-06'))
table('resource_screen.csv',checks)
for p in progs:
    p['diagnostic_resource']=next((x for x in checks if x['programme_id']==p['programme_id']),{'status':'NOT_RUN','reason':'Прямые альтернативы требуют принятого P03 block matrix; partner/event/international зависят от договора/дат.'})
    p['month_policy']=[dict(month=f'{year}-{month:02}',season='зима' if month in [1,2,12] else 'лето' if month in [6,7,8] else 'межсезонье',frequency_policy='кандидатная частота, требуется P05/P03 решение',start_gate='P03 commercial_ready + crew/MRO/contracts; 2027 новых SJ не раньше H2',status='CONDITIONAL_NOT_PUBLISHED') for year in [2027,2028] for month in range(1,13)]
dump('programme_candidates.json',{'schema':'KZN-stageA-v1; producer proposal, НЕ готовый P06 evaluation bundle','resource_groups':{'G1':'одна активная линия + один договорный shared contingency tail; доступность и цена UNKNOWN','G2':'две активные линии + тот же по определению shared contingency tail; не один и тот же физический резерв одновременно для несовместимых программ','G0':'без добавления flight tails; ресурс существующих и партнёра всё равно расходуется','G1_EVENT_WINDOW':'один выделенный хвост только на конкретное окно; сравнивать на тех же датах'},'programmes':progs,'calendar_rules':{'phased':'R1/C1/D1 при одном реально готовом борте; W2/R2/D2 при двух; не считатьпоставкуготовностью','partial':'допустим меньший локальный модуль/частота; пересчитать slots/crew и обязательства','delay':'сдвиг только будущих непринятых действий; сохранять sunk/проданные поездки','zero_new_aircraft':'KEEP и organisational P0; R1/C1/D1/W2 допустимы только при явно освобождённом существующем ресурсе с полной потерей его прежнего задания','tu214':'0 новых Ту214 не отменяет основнойCASE_SJ'}})

hyp=[]
